mapper.update:
UPDATE user_memories
SET is_active = FALSE,
    updated_at = NOW()
WHERE id = #{memoryId}
    AND user_id = #{userId}
    AND is_active = TRUE

mapper.select:
SELECT id, user_id, content, is_active, created_at, updated_at
FROM user_memories
WHERE user_id = #{userId}
    AND is_active = TRUE
ORDER BY updated_at DESC, id DESC
LIMIT #{limit}
